CREATE TRIGGER RefCusProfileQuestionAnswerListLanguage_Combined
	ON RefCusProfileQuestionAnswerListLanguage
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		XAL_DataSetPK = XQ4_XQ2_Question,
		XAL_DataSetCode = 'XQ2'
		FROM RefCusProfileQuestionAnswerListLanguage t
		JOIN inserted ON t.XAL_PK = inserted.XAL_PK
		LEFT JOIN RefCusProfileQuestionAnswerList ON inserted.XAL_XQ4_QuestionAnswer = XQ4_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.XAL_DataSetPK, t.XAL_DataSetCode
	FROM RefCusProfileQuestionAnswerListLanguage t
	JOIN inserted ON t.XAL_PK = inserted.XAL_PK
	UNION
	SELECT XAL_DataSetPK, XAL_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

